insert into public.recipes (id,owner_id,published,title,description,minutes,base_servings,diets,budget,color,art,category,steps,details,equipment) values
('mercimek',null,true,'Kırmızı mercimek çorbası','Bir tencere sıcaklık. Havuç ve patatesle kıvam alan, evin en tanıdık çorbası.',30,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#E7AA60','soup','soup','["Mercimeği süzgeçte yıka. Soğan, havuç ve patatesi küçük doğra.","Zeytinyağında soğanı yumuşat. Havuç ve patatesi ekleyip birkaç dakika çevir.","Mercimek ve suyu ekle. Kaynayınca kısık ateşte, malzemeler yumuşayana kadar yaklaşık 25 dakika pişir.","Pürüzsüz olana kadar blenderdan geçir. Tuz ve kimyonu ekle; gerekirse sıcak suyla kıvamını aç."]'::jsonb,'{"prepMinutes":5,"cookMinutes":25,"restMinutes":0,"difficulty":"easy","tips":["Mercimeği yıkarken suyu birkaç kez değiştir; üzerindeki nişasta azalsın.","Blenderdan önce tencereyi ocaktan al. Kıvamı sıcak suyu azar azar ekleyerek ayarla."],"servingSuggestion":"Limonu sofrada sun. Yanına çoban salatası ve bir dilim ekmek yakışır."}'::jsonb,array['hob','blender']::text[]),
('menemen',null,true,'Tavada menemen','Olgun domates, yeşil biber ve yumuşacık yumurta. Günün her saatine yakışır.',20,2,array['vegetarian','glutenFree']::text[],'economic','#D67D55','eggs','breakfast','["Domatesleri küçük küpler halinde doğra, biberleri ince dilimle.","Zeytinyağını tavada ısıtıp biberleri yumuşat. Domatesi ve tuzu ekle.","Domatesler suyunu biraz çekince yumurtaları ekle. Karıştırarak istediğin kıvama gelene kadar pişir."]'::jsonb,'{"prepMinutes":5,"cookMinutes":15,"restMinutes":0,"difficulty":"easy","tips":["Domatesin suyu azalmadan yumurtayı ekleme; aksi halde menemen fazla sulu olur.","Yumurta eklendikten sonra ateşi kıs; tabanı tutmadan tamamen pişir."],"servingSuggestion":"Tavadan sıcak servis et. Yanına salatalık ve zeytin koyabilirsin."}'::jsonb,array['hob']::text[]),
('bulgur',null,true,'Sebzeli bulgur pilavı','Tane tane bulgur, bol sebze. Ertesi güne de kalan bereketli bir tencere.',30,4,array['vegan','vegetarian']::text[],'economic','#C79851','rice','main','["Soğan ve biberi doğra, zeytinyağında yumuşat.","Salçayı ekleyip çevir. Küp doğranmış domatesleri ekle, birkaç dakika pişir.","Yıkanmış bulguru, sıcak suyu ve tuzu ekle. Kapağı kapalı, kısık ateşte suyunu çekene kadar pişir.","Ocağı kapatıp 10 dakika dinlendir. Çatalla havalandırarak servis et."]'::jsonb,'{"prepMinutes":5,"cookMinutes":15,"restMinutes":10,"difficulty":"easy","tips":["Bulgurun cinsi su ihtiyacını değiştirir; paket önerisini kontrol et.","Dinlenme sırasında kapağı açma; sonrasında çatalla nazikçe havalandır."],"servingSuggestion":"Yoğurtlu kabak veya çoban salatasıyla tamamla."}'::jsonb,array['hob']::text[]),
('nohut',null,true,'Nohutlu pirinç pilavı','Az malzemeyle doyurucu bir klasik. Haşlanmış nohutla pratikleşir.',30,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#DEC78B','rice','main','["Pirinci suyu berraklaşana kadar yıka ve süz.","Zeytinyağında pirinci birkaç dakika çevir. Haşlanmış nohudu ekle.","Sıcak su, tuz ve karabiberi ekle. Kapağı kapalı, kısık ateşte suyunu çekene kadar pişir.","Ocağı kapat, 10 dakika dinlendirip servis et."]'::jsonb,'{"prepMinutes":5,"cookMinutes":15,"restMinutes":10,"difficulty":"easy","tips":["Bu tarif haşlanmış, süzülmüş nohutla hazırlanır; kuru nohut aynı gramajla kullanılamaz.","Pirinç suyunu çekince ocağı kapat. Dinlenmeden karıştırmak taneleri kırabilir."],"servingSuggestion":"Limonlu salata ve yoğurtla sofraya çıkar."}'::jsonb,array['hob']::text[]),
('kabak',null,true,'Yoğurtlu kabak','Hafifçe kızarmış kabak ve sarımsaklı yoğurt. Sofraya ferah bir dokunuş.',25,2,array['vegetarian','glutenFree']::text[],'balanced','#94AD70','greens','side','["Kabakları yıka, yarım ay şeklinde dilimle ve kurula.","Geniş tavada zeytinyağı ile, ara sıra çevirerek yumuşayıp renk alana kadar pişir.","Yoğurdu ezilmiş sarımsak ve tuzla karıştır. Ilınmış kabağın üzerine gezdir."]'::jsonb,'{"prepMinutes":10,"cookMinutes":15,"restMinutes":0,"difficulty":"easy","tips":["Kabağı kurulayarak tavaya al; fazla su kızarmasını zorlaştırır.","Yoğurdu, kabak çok sıcakken ekleme; önce ılımasını bekle."],"servingSuggestion":"Bulgur pilavının ya da fırın sebzelerinin yanında sun."}'::jsonb,array['hob']::text[]),
('tavuk',null,true,'Sebzeli tavuk sote','Tek tavada renkli, doyurucu bir akşam yemeği. Yanına sade pilav çok yakışır.',35,4,array['glutenFree']::text[],'flexible','#BE8F64','stew','main','["Tavuk ve sebzeleri ayrı tahtalarda doğra.","Tavuğu geniş tavada zeytinyağıyla çevir. Soğan ve biberleri ekle.","Domates, tuz ve karabiberi ekle. Tavuk tamamen pişene kadar kapağı kapalı pişir. Çiğ tavukla temas eden araçları temizle."]'::jsonb,'{"prepMinutes":10,"cookMinutes":25,"restMinutes":0,"difficulty":"easy","tips":["Tavukları benzer büyüklükte doğra; pişmeleri daha eşit olur.","Tavayı aşırı doldurma; gerekiyorsa tavuğu iki partide çevir."],"servingSuggestion":"Bulgur pilavı ve mevsim salatasıyla tamamla."}'::jsonb,array['hob']::text[]),
('ispanak',null,true,'Zeytinyağlı ıspanak','Pirinçle tamamlanan yeşil bir tencere. Limonla servis et, tadı açılsın.',30,4,array['vegan','vegetarian','glutenFree']::text[],'balanced','#6F965E','greens','main','["Ispanağı bol suda iyice yıka, süz ve iri doğra.","Doğranmış soğanı zeytinyağında yumuşat, salçayı ekle.","Ispanak, yıkanmış pirinç, su ve tuzu ekle. Kısık ateşte pirinçler yumuşayana kadar pişir.","Biraz dinlendir, limon suyuyla servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":20,"restMinutes":0,"difficulty":"easy","tips":["Ispanağın saplarını ince doğrayıp yapraklarla birlikte kullanabilirsin.","Ispanak kendi suyunu salar; ilave suyu kontrollü ekle."],"servingSuggestion":"Limonu servis sırasında ekle. İstersen yoğurdu ayrı bir kasede sun."}'::jsonb,array['hob']::text[]),
('fasulye',null,true,'Ev usulü kuru fasulye','Haşlanmış fasulyeyle kısa yoldan ev yemeği. Salçalı suyuna ekmek banmalık.',35,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#C18459','stew','main','["Soğanı yemeklik doğra ve zeytinyağında yumuşat.","Salça ve doğranmış domatesi ekleyip birkaç dakika pişir.","Haşlanmış fasulye, sıcak su, tuz ve kimyonu ekle.","Kısık ateşte yaklaşık 20 dakika, sos koyulaşana kadar pişir. Biraz dinlendirerek servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":20,"restMinutes":5,"difficulty":"easy","tips":["Haşlanmış fasulyeyi sonradan ekleyerek dağılmasını azalt.","Sosu koyulaştırmak için son birkaç dakika kapağı açık pişir."],"servingSuggestion":"Pirinç pilavı ve soğanlı salatayla klasik bir sofra kur."}'::jsonb,array['hob']::text[]),
('ezogelin',null,true,'Naneli ezogelin çorbası','Mercimek, pirinç ve ince bulgur aynı tencerede. Nane kokusuyla tamamlanan sıcacık bir başlangıç.',40,4,array['vegan','vegetarian']::text[],'economic','#D68D4C','soup','soup','["Soğanı küçük doğra. Mercimek, pirinç ve bulguru ayrı ayrı yıka.","Soğanı zeytinyağında 5 dakika yumuşat. Salçayı ekleyip bir dakika çevir.","Mercimek, pirinç, bulgur ve sıcak suyu ekle. Kaynayınca ateşi kıs; yaklaşık 30 dakika, tahıllar yumuşayana kadar pişir.","Tuz ve kuru naneyi ekle. Kıvamı koyuysa sıcak suyla aç, birkaç dakika dinlendirerek servis et."]'::jsonb,'{"prepMinutes":5,"cookMinutes":35,"restMinutes":0,"difficulty":"easy","tips":["Tahıllar bekledikçe su çeker; servis öncesi kıvamını kontrol et.","Naneyi uzun süre kavurmak yerine son aşamada ekle."],"servingSuggestion":"Limon dilimiyle sıcak sun. Yanına mücver ekleyebilirsin."}'::jsonb,array['hob']::text[]),
('kisir',null,true,'Bol yeşillikli kısır','İnce bulgur, limon ve çıtır yeşillikler. Öğle sofrasına ya da çay saatine renk katar.',25,4,array['vegan','vegetarian']::text[],'economic','#C66F45','rice','salad','["İnce bulguru geniş bir kaba al. Sıcak suyu ekle, üzerini kapatıp 10 dakika şişmeye bırak.","Maydanoz ve taze soğanı ince kıy. Salatalık ve domatesi küçük küpler halinde doğra.","Ilık bulgura salça, zeytinyağı, limon suyu ve tuzu ekleyip iyice karıştır.","Sebzeleri ve yeşillikleri ekle. Ezmeden karıştırıp servis et."]'::jsonb,'{"prepMinutes":15,"cookMinutes":0,"restMinutes":10,"difficulty":"easy","tips":["İnce bulgur kullan; pilavlık bulgur aynı bekleme süresinde yumuşamaz.","Yeşillikleri bulgur ılıdıktan sonra ekle ki diri kalsın."],"servingSuggestion":"Marul yapraklarında ya da küçük kaselerde servis et."}'::jsonb,array['hob']::text[]),
('coban',null,true,'Limonlu çoban salatası','Domates, salatalık ve biberin en sade hali. Ana yemeğinin yanına ferah bir tabak.',15,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#91A76B','greens','salad','["Sebzeleri ve maydanozu iyice yıka. Domates, salatalık ve biberi küçük doğra.","Soğanı ince dilimle; maydanozu kıy. Tüm sebzeleri geniş bir kasede birleştir.","Limon suyu, zeytinyağı ve tuzu karıştır. Servisten hemen önce salataya gezdir."]'::jsonb,'{"prepMinutes":15,"cookMinutes":0,"restMinutes":0,"difficulty":"easy","tips":["Sebzeleri benzer boyutta doğramak her lokmanın dengeli olmasını sağlar.","Tuz ve sosu son anda ekle; salatanın sulanmasını azalt."],"servingSuggestion":"Tencere yemekleri ve pilavların yanında sun."}'::jsonb,array[]::text[]),
('omlet',null,true,'Patatesli tava omleti','Altı hafif kızarmış patates, üstünde yumuşak yumurta. İki kişilik doyurucu bir kahvaltı.',25,2,array['vegetarian','glutenFree']::text[],'economic','#EAC764','eggs','breakfast','["Patatesi soyup küçük küpler halinde doğra; yıkayıp iyice kurula.","Zeytinyağını yapışmaz tavada ısıt. Patatesleri orta ateşte, sık çevirerek yaklaşık 15 dakika yumuşatıp kızart.","Yumurtayı tuz ve karabiberle çırp, patateslerin üzerine dök.","Kapağını kapatıp kısık ateşte yumurta tamamen pişene kadar pişir. Dilimleyerek servis et."]'::jsonb,'{"prepMinutes":5,"cookMinutes":20,"restMinutes":0,"difficulty":"easy","tips":["Patates küplerini küçük tut ve yumurtadan önce tamamen yumuşat.","Tavanın kapağını kapatmak yumurtanın üst kısmının da pişmesine yardımcı olur."],"servingSuggestion":"Domates, salatalık ve yeşillikle kahvaltı tabağına dönüştür."}'::jsonb,array['hob']::text[]),
('makarna',null,true,'Domates soslu makarna','Sarımsaklı domates sosu ve bir avuç maydanoz. Yoğun günlere kolay bir ev yemeği.',20,2,array['vegan','vegetarian']::text[],'economic','#D97649','rice','main','["Suyu bir tencerede kaynat. Tuzun yarısını ve yumurtasız makarnayı ekle; paketteki süreye göre haşla.","Bu sırada sarımsağı ince doğra. Zeytinyağında kısa süre çevir; rendelenmiş domatesi ve kalan tuzu ekle.","Sosu orta ateşte yaklaşık 10 dakika koyulaştır. Makarnanın suyundan biraz ayırıp makarnayı süz.","Makarnayı sosla birleştir. Gerekiyorsa ayırdığın sudan ekle, kıyılmış maydanozla tamamla."]'::jsonb,'{"prepMinutes":5,"cookMinutes":15,"restMinutes":0,"difficulty":"easy","tips":["Sos ve makarnayı aynı anda pişirerek zamandan kazan.","Süzmeden önce haşlama suyundan ayır; nişastalı su sosu makarnaya bağlar."],"servingSuggestion":"Çoban salatasıyla servis et; maydanozu sofraya çıkarmadan hemen önce ekle."}'::jsonb,array['hob']::text[]),
('firinsebze',null,true,'Kekikli fırın sebzeleri','Patates, kabak ve havuç bir tepside buluşuyor. Pilavın ya da ana yemeğin yanına rengârenk bir eşlikçi.',50,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#C7A768','greens','side','["Fırını 200 dereceye ısıt. Patates ve havucu küçük parçalar halinde, kabağı yarım ay şeklinde doğra; biberi iri doğra.","Sebzeleri zeytinyağı, kekik ve tuzla karıştır.","Yağlı kağıt serili tepsiye tek kat halinde yay. Yaklaşık 35–40 dakika, patatesler yumuşayıp kenarlar kızarana kadar pişir.","Pişirmenin yarısında sebzeleri çevir. Fırından alıp sıcak servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":40,"restMinutes":0,"difficulty":"easy","tips":["Patates ve havucu kabaktan daha küçük kes; pişme süreleri birbirine yaklaşsın.","Tepsiyi doldurup üst üste yığma; sebzeler tek kat olduğunda daha iyi renk alır."],"servingSuggestion":"Yoğurtlu sosla veya ana yemeğin yanında servis et."}'::jsonb,array['oven']::text[]),
('mantar',null,true,'Biberli mantar sote','Mantarın lezzeti domatesli sosta toplanıyor. Yanına bulgur pilavıyla sade, bitkisel bir sofra.',25,2,array['vegan','vegetarian','glutenFree']::text[],'balanced','#A8845F','stew','main','["Mantarları temizleyip dilimle. Soğan ve biberi doğra; domatesi küçük küpler halinde kes.","Geniş tavada yağı ısıt. Soğan ve biberi 4–5 dakika çevir.","Mantarları ekle; orta-yüksek ateşte, suyunu salıp büyük ölçüde çekene kadar pişir.","Domates, tuz ve karabiberi ekle. Yaklaşık 8 dakika, domatesler sos haline gelene kadar pişir."]'::jsonb,'{"prepMinutes":10,"cookMinutes":15,"restMinutes":0,"difficulty":"easy","tips":["Geniş tava kullan; mantarlar üst üste yığılırsa daha çok su salar.","Domatesi, mantarların bıraktığı su büyük ölçüde çekildikten sonra ekle."],"servingSuggestion":"Bulgur pilavı ile bir ana öğüne dönüştür."}'::jsonb,array['hob']::text[]),
('sutlac',null,true,'Tarçınlı ev sütlacı','Pirinç, süt ve hafif bir tarçın kokusu. 45 dakikada pişer; soğuk servis için ayrıca 2 saat dinlenir.',165,4,array['vegetarian','glutenFree']::text[],'economic','#E9DCC4','soup','dessert','["Pirinci yıkayıp suyla birlikte tencereye al. Kısık ateşte yaklaşık 15 dakika, pirinç yumuşayıp suyun çoğunu çekene kadar pişir.","Sütü ekle. Kaynamaya başlayınca altını kıs; dibini tutturmadan, sık karıştırarak yaklaşık 20 dakika pişir.","Şekeri ekleyip 5 dakika daha karıştırarak pişir. Sıcakken biraz akışkan olmalı; soğudukça koyulaşır.","Kaselere paylaştır. Buharı geçince buzdolabına alıp yaklaşık 2 saat soğut. Tarçın serperek servis et."]'::jsonb,'{"prepMinutes":5,"cookMinutes":40,"restMinutes":120,"difficulty":"easy","tips":["Pirinci önce suda yumuşat; sütü ekledikten sonra sık sık tabanını karıştır.","Sıcakken hafif akışkan bırak; soğudukça koyulaşır."],"servingSuggestion":"Soğuk servis et. Tarçını sofraya çıkarırken ekle."}'::jsonb,array['hob','fridge']::text[]),
('yayla',null,true,'Naneli yayla çorbası','Yoğurt ve pirincin yumuşak kıvamı, üzerinde naneli zeytinyağı. Terbiyesini adım adım hazırlıyoruz.',35,4,array['vegetarian']::text[],'economic','#E8DDC7','soup','soup','["Pirinci yıkayıp suyla tencereye al. Kaynayınca ateşi kıs; yaklaşık 15 dakika, pirinçler yumuşayana kadar pişir.","Yoğurt, kabuksuz tartılmış yumurta ve unu ayrı bir kapta pürüzsüz olana kadar çırp.","Sıcak pirinç suyundan bir kepçeyi yoğurda azar azar ekleyip sürekli çırp. Bir kepçe daha ekleyerek terbiyeyi ılıt.","Ilık terbiyeyi tencereye ince bir akışla dökerken çorbayı karıştır. Kısık ateşte 8–10 dakika karıştırarak pişir; güçlü biçimde kaynatma.","Küçük tavada yağı hafifçe ısıt, naneyi ekleyip ocaktan al. Çorbaya karıştır, tuzunu ekleyip sıcak servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":25,"restMinutes":0,"difficulty":"medium","tips":["Terbiyeyi sıcak suyla azar azar ılıtmak yoğurdun kesilmesini azaltır.","Terbiye tencereye girdikten sonra güçlü kaynatma ve karıştırmayı bırakma."],"servingSuggestion":"Naneli yağı servis sırasında paylaştır; yanında zeytinyağlı sebze sun."}'::jsonb,array['hob']::text[]),
('pirasa',null,true,'Zeytinyağlı pırasa','Havuç, pirinç ve limonla hafif ekşili bir tencere. Sebzeleri dağıtmadan, yavaşça pişir.',45,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#A4B87A','greens','main','["Pırasanın köklerini ve sert dış yapraklarını ayır. Kat aralarını iyice yıka; 2–3 cm kalınlığında dilimle. Havucu ince halkalar halinde kes.","Zeytinyağını geniş tencerede ısıt. Havuçları orta ateşte yaklaşık 5 dakika çevir.","Pırasaları ekle, ezmeden karıştır ve 3 dakika yumuşat. Yıkanmış pirinci üzerine dağıt.","Su, limon suyu ve tuzu ekle. Kapağı kapalı, kısık ateşte yaklaşık 25 dakika pişir. Pirinç ve pırasanın yumuşaklığını kontrol et.","Ocaktan alıp 5 dakika dinlendir. Pırasaları dağıtmamak için geniş bir kaşıkla servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":30,"restMinutes":5,"difficulty":"easy","tips":["Pırasanın katları arasında toprak kalmaması için kesmeden önce ve sonra yıka.","Sık sık kaşıkla karıştırmak yerine tencereyi hafifçe salla."],"servingSuggestion":"Limon dilimleriyle ılık servis et. Yanına yoğurt koyabilirsin."}'::jsonb,array['hob']::text[]),
('bezelye',null,true,'Havuçlu patatesli bezelye','Renkli sebzeler, salçalı sos ve tek tencere. Taze ya da dondurulmuş bezelyeyle yapılabilen ev yemeği.',40,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#A3B969','stew','main','["Soğanı küçük doğra. Patates ve havucu birbirine yakın büyüklükte, yaklaşık 1–2 cm küpler halinde kes.","Soğanı yağda 5 dakika yumuşat. Havucu ekleyip 3 dakika çevir; salçayı ekleyip bir dakika karıştır.","Patates ve bezelyeyi ekle. Dondurulmuş bezelye kullanıyorsan paket talimatını da kontrol et.","Sıcak su ve tuzu ekle. Kaynayınca kısık ateşe al; kapağı kapalı yaklaşık 20 dakika, sebzeler yumuşayana kadar pişir.","Patatesi çatalla kontrol et. Sos çok suluysa kapağı açık birkaç dakika daha pişir; sebzeleri ezmeden servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":30,"restMinutes":0,"difficulty":"easy","tips":["Patates ve havuç küplerini küçük ve eşit kes; bezelyeyle birlikte yumuşasın.","Sebzenin cinsine göre süre değişebilir; patatesi çatalla kontrol et."],"servingSuggestion":"Sade pirinç pilavı veya bir kase yoğurtla tamamla."}'::jsonb,array['hob']::text[]),
('barbunya',null,true,'Zeytinyağlı barbunya','Haşlanmış barbunyayla pratikleşen klasik. Havuç ve patatesli domates sosunda ağır ağır lezzetlenir.',40,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#C78B64','stew','main','["Haşlanmış barbunyayı süz. Soğan ve sarımsağı küçük doğra; havuç ve patatesi küçük küpler halinde kes.","Soğanı zeytinyağında 5 dakika yumuşat. Havuç ve patatesi ekleyip 5 dakika çevir.","Sarımsak, salça ve rendelenmiş domatesi ekle. Orta ateşte 3 dakika karıştır.","Barbunya, sıcak su ve tuzu ekle. Kapağı kapalı, kısık ateşte yaklaşık 15 dakika pişir; patatesin yumuşadığını kontrol et.","Ocağı kapatıp 5 dakika dinlendir. Bakliyatı ezmeden karıştırıp servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":25,"restMinutes":5,"difficulty":"easy","tips":["Gramaj haşlanmış ve süzülmüş barbunya içindir; konserve kullanırsan suyunu süz.","Sebzeleri barbunyadan önce pişirmeye başla; bakliyatın dağılmasını önlersin."],"servingSuggestion":"Ilık servis et; yanında çoban salatası iyi gider."}'::jsonb,array['hob']::text[]),
('mucver',null,true,'Fırında kabak mücver','Kabak, dereotu ve beyaz peynirle hazırlanan küçük fırın mücverler. Kızartmadan, tek tepside.',50,4,array['vegetarian']::text[],'balanced','#BAB579','greens','main','["Fırını 190 dereceye ısıt. Kabağı iri rendele, temiz bir bez veya süzgeçle fazla suyunu iyice sık. Gramaj, sıkılmadan önceki ayıklanmış kabak içindir.","Dereotu ve taze soğanı ince kıy. Yumurtaları geniş bir kapta çırp; ezilmiş peynir ve yağı ekle.","Kabak, yeşillikler, un, tuz ve karabiberi ekle. Kaşıkla alınabilecek yoğun bir karışım elde edene kadar karıştır.","Pişirme kağıdı serili tepsiye kaşıkla küçük mücverler yerleştir. Aralarında boşluk bırakıp her birini yaklaşık 1,5 cm kalınlığında düzleştir.","Yaklaşık 30 dakika, üstleri kızarıp içi tamamen pişene kadar fırınla. Tepside 5 dakika dinlendirip servis et."]'::jsonb,'{"prepMinutes":15,"cookMinutes":30,"restMinutes":5,"difficulty":"easy","tips":["Kabağın suyunu iyice sıkmak daha az unla şekil alan bir karışım sağlar.","Peynir tuzluysa ilave tuzu azalt; mücverleri eşit kalınlıkta yay."],"servingSuggestion":"Yoğurdu ayrı kasede ve çoban salatasıyla birlikte sun."}'::jsonb,array['oven']::text[]),
('semizotu',null,true,'Yoğurtlu semizotu salatası','Çıtır semizotu, salatalık ve sarımsaklı yoğurt. Ocak açmadan, 15 dakikada sofrada.',15,4,array['vegetarian','glutenFree']::text[],'economic','#B4C48A','greens','salad','["Semizotunun kalın saplarını ayır. Yaprak ve ince sapları bol suyla birkaç kez yıka, süzüp iyice kurut.","Salatalığı yıka ve küçük küpler halinde doğra. Sarımsağı ez.","Yoğurt, sarımsak ve tuzu geniş bir kapta pürüzsüz olana kadar karıştır.","Semizotu ve salatalığı servisten hemen önce yoğurda ekle. Nazikçe karıştır, üzerine zeytinyağını gezdir."]'::jsonb,'{"prepMinutes":15,"cookMinutes":0,"restMinutes":0,"difficulty":"easy","tips":["Yaprakları iyice kurut; ıslak semizotu yoğurdu sulandırır.","Yoğurtla karıştırma işini son ana bırak."],"servingSuggestion":"Bulgur pilavı veya fırında mücverin yanında soğuk sun."}'::jsonb,array[]::text[]),
('brokoli',null,true,'Sütlü brokoli çorbası','Kremasız, patatesle kıvam alan yeşil çorba. Brokolinin saplarını da değerlendir.',35,4,array['vegetarian','glutenFree']::text[],'balanced','#ADBC8C','soup','soup','["Brokoliyi yıka ve küçük çiçeklere ayır. Sapın sert dışını soyup iç kısmını küçük doğra. Patates ve soğanı küp doğra.","Soğanı zeytinyağında yaklaşık 5 dakika yumuşat. Patates, brokoli sapı ve suyu ekle; 10 dakika pişir.","Brokoli çiçeklerini ekleyip 8–10 dakika daha, tüm sebzeler yumuşayana kadar pişir.","Tencereyi ocaktan al. Sıçratmadan, el blenderıyla pürüzsüz hale getir.","Süt, tuz ve karabiberi ekle. Yeniden kısık ateşe al, birkaç dakika karıştırarak ısıt; kıvamı gerekirse sıcak suyla aç."]'::jsonb,'{"prepMinutes":10,"cookMinutes":25,"restMinutes":0,"difficulty":"easy","tips":["Brokolinin soyulmuş sapları çorbada kullanılabilir; çiçeklerden önce tencereye ekle.","Sütü ekledikten sonra ateşi kıs ve karıştırarak ısıt."],"servingSuggestion":"Karabiberi servis sırasında ekle; yanında kızarmış ekmek sunabilirsin."}'::jsonb,array['hob','blender']::text[]),
('irmik',null,true,'Tarçınlı sütlü irmik','Az malzemeli, kaşık kaşık bir sütlü tatlı. 20 dakikalık hazırlıktan sonra buzdolabında dinlenir.',140,4,array['vegetarian']::text[],'economic','#E6D4AF','soup','dessert','["Süt, irmik ve şekeri soğukken tencereye al. İrmiğin topaklanmaması için çırpıcıyla karıştır.","Orta-kısık ateşte tabanını sıyırarak sürekli karıştır. Yaklaşık 10–15 dakika içinde kıvam alıp hafifçe kaynamaya başlayacak.","Kısık ateşte 2–3 dakika daha karıştırarak pişir. Kaşıktan kalın bir şerit halinde akınca ocaktan al.","Küçük kaselere paylaştır. Buharı geçince buzdolabına alıp yaklaşık 2 saat soğut.","Servisten önce üzerine tarçın serp. Soğudukça kıvamı koyulaşacağı için sıcakken çok katı olmasını bekleme."]'::jsonb,'{"prepMinutes":5,"cookMinutes":15,"restMinutes":120,"difficulty":"easy","tips":["Süt, şeker ve irmiği ocak açılmadan karıştır; topaklanma azalır.","Tabanı sürekli sıyırarak karıştır ve sıcak kıvamın soğuyunca koyulaşacağını unutma."],"servingSuggestion":"Küçük kaselerde soğuk servis et; tarçını son anda ekle."}'::jsonb,array['hob','fridge']::text[]),
('airfryer-sebze',null,true,'Airfryer’da baharatlı sebzeler','Kabak, patates ve havuç; az yağla, küçük partiler halinde kızaran renkli bir eşlikçi.',35,2,array['vegan','vegetarian','glutenFree']::text[],'economic','#D9AC67','greens','side','["Patates ve havucu küçük, eşit parçalar halinde; kabağı biraz daha iri doğra. Yıkadığın sebzeleri kurula.","Patates ve havucu zeytinyağının yarısı, tuz ve kekikle karıştır. Cihazın kullanım kılavuzuna göre 190 dereceye hazırlanan sepete tek kat yerleştir.","Yaklaşık 10 dakika pişir. Kabağı kalan yağla karıştırıp ekle; sepeti salla ve 10–15 dakika daha, sebzeler yumuşayana kadar pişir.","Sepet küçükse birkaç parti hazırla; süre cihaz ve kesim büyüklüğüne göre değişir. Sıcak servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":25,"restMinutes":0,"difficulty":"easy","tips":["Sepeti doldurmak yerine tek kat yerleşim kullan.","Patates ve havucun pişmesini çatalla kontrol et; kabağı daha sonra ekle."],"servingSuggestion":"Yoğurtlu bir sosla veya ana yemeğin yanında servis edebilirsin."}'::jsonb,array['airfryer']::text[]),
('airfryer-mucver',null,true,'Airfryer’da peynirli mücver','Suyu sıkılmış kabak, beyaz peynir ve dereotuyla küçük, yumuşak mücverler.',35,2,array['vegetarian']::text[],'balanced','#9BAA65','greens','main','["Kabağı rendele ve temiz bir bezle suyunu iyice sık. Dereotunu ince kıy, peyniri ufala.","Kabak, yumurta, un, peynir, dereotu ve karabiberi karıştır. Karışımı cihazına uygun küçük, yağlanmış ısıya dayanıklı kalıplara paylaştır.","Kalıpları sepetin hava dolaşımını engellemeyecek şekilde yerleştir. 180 derecede yaklaşık 20 dakika, orta kısmı tamamen pişene kadar pişir; gerekirse süreyi uzat.","Cihazın kullanım kılavuzuna uy, boş pişirme kâğıdı kullanma. Kalıpları dikkatle çıkarıp 5 dakika dinlendir."]'::jsonb,'{"prepMinutes":10,"cookMinutes":20,"restMinutes":5,"difficulty":"easy","tips":["Kabağın suyunu iyi sıkmak kıvamı belirler.","Kalıpları fazla doldurma; cihaz küçükse partiler halinde pişir."],"servingSuggestion":"Yanına domatesli bir salata hazırlayabilirsin."}'::jsonb,array['airfryer']::text[]),
('cilbir',null,true,'Sarımsaklı yoğurtlu çılbır','Sarımsaklı yoğurdun üzerine suda pişmiş yumurta, en üste naneli zeytinyağı. Kahvaltıya sıcak bir tabak.',20,2,array['vegetarian','glutenFree']::text[],'economic','#E8D9BA','eggs','breakfast','["Yoğurdu ezilmiş sarımsak ve tuzun yarısıyla karıştır. Servis tabaklarına paylaştır.","Suyu geniş bir tencerede kaynat, ardından hafifçe titreşecek kadar ateşi kıs. Yumurtaları tek tek küçük bir kaseye kır; ağırlık kabuksuz toplamdır.","Yumurtaları suya kenardan yavaşça bırak. Birbirine yapışmayacak aralıklarla, beyazı ve sarısı katılaşana kadar yaklaşık 6–8 dakika pişir; gerekirse partiler halinde hazırla.","Delikli kaşıkla çıkarıp suyunu süzdür ve yoğurdun üzerine koy. Küçük tavada yağı hafifçe ısıt, naneyi ve kalan tuzu ekleyip ocaktan al; yumurtaların üzerine gezdir."]'::jsonb,'{"prepMinutes":5,"cookMinutes":15,"restMinutes":0,"tips":["Güçlü kaynayan su yumurtayı dağıtabilir; suyu hafif hareketli tut.","Bu tarifte yumurtanın beyazı ve sarısı tamamen pişirilir. Pişirme süresi yumurtanın büyüklüğüne göre değişir."],"servingSuggestion":"Yanında domates ve salatalıkla sıcak servis et.","difficulty":"easy"}'::jsonb,array['hob']::text[]),
('peynirli-krep',null,true,'Maydanozlu peynirli krep','İnce krep hamuruna beyaz peynir ve maydanoz. Tavadan sıcak çıkan, katlayıp paylaşmalık bir kahvaltı.',30,2,array['vegetarian']::text[],'balanced','#D9BA78','eggs','breakfast','["Yumurta ve sütü çırp. Unu ve tuzu azar azar ekleyip pürüzsüz, akışkan bir hamur hazırla. Yağın üçte birini hamura karıştır.","Maydanozu yıkayıp kurula, ince kıy. Beyaz peyniri ufalayıp maydanozla karıştır.","Yapışmaz tavayı orta ateşte ısıt; kalan yağdan çok az sür. Küçük bir kepçe hamuru tavaya döküp ince yay.","Altı renk alınca çevir; iki yüzü de pişsin ve ıslak hamur kalmasın. Kalan hamurla yaklaşık dört ince krep hazırla; kalan yağı gerektiğinde kullan.","Peynirli harcı kreplere paylaştır. Katlayıp tavada birer dakika ısıt ve servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":20,"restMinutes":0,"tips":["Hamuru tavaya döker dökmez tavayı çevirerek incelt; kalın tabaka içte çiğ kalabilir.","Peynirin tuzuna göre eklediğin tuzu azaltabilirsin. Daha fazla porsiyonda tava partileri süreyi uzatır."],"servingSuggestion":"Taze domates ve sade bir yeşillik tabağıyla sun.","difficulty":"easy"}'::jsonb,array['hob']::text[]),
('peynirli-biber',null,true,'Domatesli peynirli biber','Yumuşayan yeşil biber, suyunu çeken domates ve ufalanmış beyaz peynir. Yumurtasız, tek tavada kahvaltı.',20,2,array['vegetarian','glutenFree']::text[],'balanced','#B7AD6B','greens','breakfast','["Biberlerin sap ve çekirdeklerini ayır, ince doğra. Domatesleri küçük küpler halinde kes.","Yağı tavada ısıt. Biberleri orta ateşte, ara sıra karıştırarak 7–8 dakika yumuşat.","Domatesleri ekle. Fazla suyu azalıncaya kadar yaklaşık 5 dakika pişir.","Peyniri ufalayıp karabiberle birlikte tavaya ekle. Kısık ateşte 1–2 dakika ısıtıp servis et."]'::jsonb,'{"prepMinutes":5,"cookMinutes":15,"restMinutes":0,"tips":["Peynir tuzlu olduğu için malzeme listesine ayrıca tuz eklenmedi.","Domatesin fazla suyunu peynirden önce çektirmek kıvamı korur."],"servingSuggestion":"Kahvaltı sofrasına tavadan sıcak olarak getir.","difficulty":"easy"}'::jsonb,array['hob']::text[]),
('domates-corbasi',null,true,'Sütlü domates çorbası','Olgun domateslerin tadını öne çıkaran, az sütle yumuşayan klasik çorba. Unla hafifçe kıvam alır.',35,4,array['vegetarian']::text[],'economic','#D77950','soup','soup','["Domatesleri yıkayıp sap kısmını çıkar, küçük doğra. Zeytinyağını tencerede hafifçe ısıt.","Unu ekleyip kısık ateşte 1–2 dakika karıştır; yakmadan kokusunu çıkar. Domatesleri ekleyip yaklaşık 8 dakika yumuşat.","Suyu azar azar eklerken karıştır. Kaynayınca ateşi kıs ve 12–15 dakika pişir.","Tencereyi ocaktan al. Sıçratmadan el blenderıyla pürüzsüzleştir. Sütü azar azar karıştırarak ekle, yeniden kısık ateşe al.","Tuz ve karabiberi ekle. Birkaç dakika ısıt; güçlü biçimde kaynatmadan servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":25,"restMinutes":0,"tips":["Domatesin olgunluğu lezzeti belirler; çok sulu domateste son kıvamı biraz daha pişirerek ayarla.","Blenderı tencere ocaktan alınmışken kullan; sıcak çorbayı sıçratmamak için başlığı sıvı içinde tut."],"servingSuggestion":"Sıcak servis et; yanına peynirli bir krep veya salata seçebilirsin.","difficulty":"easy"}'::jsonb,array['hob','blender']::text[]),
('sebzeli-pirinc-corbasi',null,true,'Sebzeli pirinç çorbası','Havuç, patates ve pirinçle taneli bir çorba. Son anda eklenen limon ve nane tadını tazeler.',35,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#DFC285','soup','soup','["Soğanı ince, havuç ve patatesi küçük eşit küpler halinde doğra. Pirinci yıka ve süz.","Zeytinyağında soğanı 3–4 dakika yumuşat. Havuç ve patatesi ekleyip birkaç dakika çevir.","Pirinci ve suyu ekle. Kaynayınca ateşi kıs; pirinç ve sebzeler yumuşayana kadar yaklaşık 20 dakika pişir.","Tuz ve naneyi ekle. Ocağı kapatınca limon suyunu karıştır; koyuysa azar azar sıcak suyla kıvamı aç."]'::jsonb,'{"prepMinutes":10,"cookMinutes":25,"restMinutes":0,"tips":["Küçük ve eşit sebze parçaları aynı sürede pişer.","Pirinç bekledikçe sıvı çeker; tekrar ısıtırken kıvamını kontrol et."],"servingSuggestion":"Ana yemeğin öncesinde sıcak bir başlangıç olarak sun.","difficulty":"easy"}'::jsonb,array['hob']::text[]),
('firin-limonlu-tavuk',null,true,'Fırında limonlu tavuk ve patates','Limon, sarımsak ve kekikle hazırlanan tavuk; yanında aynı tepside pişen patates ve havuç.',55,4,array['glutenFree']::text[],'flexible','#C99C68','stew','main','["Fırını 200 dereceye ısıt. Patatesleri ince elma dilimi, havuçları küçük parçalar halinde kes. Tavuk göğsünü ayrı tahtada iri, benzer kalınlıkta parçalara ayır.","Yağ, limon suyu, ezilmiş sarımsak, kekik, tuz ve karabiberi karıştır. Sebzeleri ve tavuğu bu karışımla kapla; çiğ tavukla temas eden elleri ve araçları temizle.","Geniş tepsiye tek kat yay. Yaklaşık 30–35 dakika pişir; ortasında sebzeleri dikkatle çevir.","Tavuğun en kalın kısmını gıda termometresiyle kontrol et: iç sıcaklık en az 74 °C olmalı. Sebzeler de yumuşamış olmalı; gerekirse pişirmeyi sürdür.","Fırından çıkarıp 5 dakika dinlendir. Çiğ tavukla temas etmiş sosu pişirmeden servis için kullanma."]'::jsonb,'{"prepMinutes":15,"cookMinutes":35,"restMinutes":5,"tips":["Süre tek başına pişme ölçütü değildir; parçaların kalınlığına göre değişir, iç sıcaklığı kontrol et.","Tepsi kalabalıksa iki tepsi kullan; patatesleri ince kesmek tavukla birlikte pişmelerine yardımcı olur."],"servingSuggestion":"Yanında cacık ve taze salatayla servis et.","difficulty":"easy"}'::jsonb,array['oven']::text[]),
('kabak-dolmasi',null,true,'Zeytinyağlı kabak dolması','Pirinç, domates ve dereotuyla doldurulmuş kabaklar. Tencerede yavaş pişen etsiz bir ev klasiği.',65,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#91AC70','greens','main','["Kabakları yıka, uçlarını al; uzun olanları ikiye böl. Kenarları ve tabanı delinmeyecek şekilde içlerini oy. Çıkan içleri başka bir yemek için ayır.","Pirinci yıka. Soğan ve dereotunu ince kıy, domatesleri küçük doğra. Pirinç, soğan, dereotu, domates, nane, tuzun yarısı ve yağın çoğunu karıştır.","Kabakları harçla gevşekçe doldur; pirincin şişmesi için üstte yaklaşık bir parmak boşluk bırak. Açık tarafları yukarı gelecek biçimde tencereye yerleştir.","Salça, su, kalan yağ ve tuzu karıştırıp tencerenin kenarından dök. Sıvı kabakların yaklaşık yarısına gelmeli; tencereye göre sıcak suyu azar azar ayarla.","Kaynadıktan sonra kapağı kapalı, kısık ateşte yaklaşık 35–40 dakika pişir. Pirinçler yumuşamamışsa biraz sıcak su ekleyip sürdür. Ocaktan alıp 5 dakika dinlendir."]'::jsonb,'{"prepMinutes":20,"cookMinutes":40,"restMinutes":5,"tips":["Harcı bastırarak sıkıştırma; pirinç şişerken yer ister.","Kabağın oyulan içi bu tarifin harcına dahil değildir. Alışverişte oyma öncesi ayıklanmış kabak ağırlığı kullanılır."],"servingSuggestion":"Ilık servis et; yoğurdu isteyenler ayrı bir kapta ekleyebilir.","difficulty":"medium"}'::jsonb,array['hob']::text[]),
('firinda-peynirli-makarna',null,true,'Fırında peynirli makarna','Sütlü sosla kaplanan makarna ve beyaz peynir. Üzeri hafifçe kızaran, dilimleyip paylaşmalık bir fırın yemeği.',50,4,array['vegetarian']::text[],'balanced','#DBBA79','rice','main','["Fırını 190 dereceye ısıt. Suyu kaynat, makarnayı paketindeki süreden 2 dakika kısa haşla ve süz. Listedeki su haşlama içindir, yemekte kalmaz.","Yağın küçük bir kısmıyla fırın kabını yağla. Kalan yağı tencerede ısıt; unu ekleyip 1–2 dakika karıştır.","Sütü azar azar eklerken çırp. Kısık ateşte hafifçe koyulaşana kadar pişir; karabiber ve tuzu ekle.","Makarnayı, sosu ve ufalanmış peynirin çoğunu karıştır. Fırın kabına yay, kalan peyniri üzerine dağıt.","Yaklaşık 20 dakika, içi iyice ısınıp üzeri hafifçe renk alana kadar fırınla. Dilimlemeden önce 5 dakika dinlendir."]'::jsonb,'{"prepMinutes":10,"cookMinutes":35,"restMinutes":5,"tips":["Haşlama ve sos hazırlığı pişirme süresine dahildir; makarna fırında da pişeceği için önceden çok yumuşatma.","Beyaz peynirin tuzu yüksekse eklediğin tuzu azalt. Sosu çok koyulaştırmadan makarnayla birleştir."],"servingSuggestion":"Yanında limonlu çoban salatası iyi gider.","difficulty":"easy"}'::jsonb,array['hob','oven']::text[]),
('nohutlu-sebze',null,true,'Nohutlu sebze tenceresi','Haşlanmış nohut, kabak ve havuç aynı tencerede. Salçalı sosla birleşen bol sebzeli bir akşam yemeği.',40,4,array['vegan','vegetarian','glutenFree']::text[],'economic','#C58E62','stew','main','["Soğanı ve biberi doğra. Havucu ince yarım ay, kabağı daha iri parçalar halinde kes; domatesleri küçük doğra.","Yağda soğan, havuç ve biberi yaklaşık 7 dakika yumuşat. Salçayı ekleyip kısa süre karıştır.","Domates, kabak, haşlanıp süzülmüş nohut ve suyu ekle. Kaynayınca ateşi kıs.","Tuz ve kimyonu ekleyip kapağı kapalı yaklaşık 20 dakika, sebzeler yumuşayana kadar pişir. Kabağı dağıtmadan nazikçe karıştır."]'::jsonb,'{"prepMinutes":10,"cookMinutes":30,"restMinutes":0,"tips":["Nohut miktarı kuru değil, haşlanmış ve süzülmüş ağırlıktır; sıfırdan haşlama süresi bu tarife dahil değildir.","Kabak hızlı pişer; havucu daha ince keserek aynı sürede yumuşamalarını sağla."],"servingSuggestion":"Sıcak servis et; istersen yanında sade pirinç pilavı hazırla.","difficulty":"easy"}'::jsonb,array['hob']::text[]),
('piyaz',null,true,'Limonlu fasulye piyazı','Haşlanmış kuru fasulye, ince soğan ve bol maydanoz. Limonlu zeytinyağıyla sade bir piyaz.',15,2,array['vegan','vegetarian','glutenFree']::text[],'economic','#D3C49A','greens','salad','["Haşlanmış fasulyeyi süz. Soğanı ince yarım ay doğra; tuzla hafifçe ov.","Domatesi küp doğra. Maydanozu yıkayıp kurula ve ince kıy.","Limon suyu ve zeytinyağını çırp. Fasulye, soğan, domates ve maydanozla nazikçe karıştırıp servis et."]'::jsonb,'{"prepMinutes":15,"cookMinutes":0,"restMinutes":0,"tips":["Fasulyeyi pişmiş, soğumuş ve süzülmüş olarak tart; kuru fasulye gramajıyla değiştirme.","Kaşıkla sertçe karıştırmak fasulyeyi ezer; geniş bir kapta alttan üste çevir."],"servingSuggestion":"Bir ana yemeğin yanında salata olarak sun; bu versiyonda tahin ve yumurta yoktur.","difficulty":"easy"}'::jsonb,array[]::text[]),
('nohut-salatasi',null,true,'Bol yeşillikli nohut salatası','Nohut, domates, salatalık ve taze yeşillikler. Haşlanmış nohutla kısa sürede hazırlanan renkli bir salata.',15,2,array['vegan','vegetarian','glutenFree']::text[],'economic','#BFC28B','greens','salad','["Haşlanmış nohudu süz. Domates ve salatalığı küçük küpler halinde doğra.","Taze soğan ve maydanozu yıkayıp kurula, ince kıy. Sebzeleri nohutla aynı kaba al.","Limon suyu, zeytinyağı ve tuzu karıştır. Servise yakın salataya ekle; nohudu ezmeden harmanla."]'::jsonb,'{"prepMinutes":15,"cookMinutes":0,"restMinutes":0,"tips":["Nohut miktarı haşlanmış/süzülmüş ağırlıktır; haşlama süresi verilen 15 dakikaya dahil değildir.","Sebzelerin üzerinde kalan su sosu sulandırır; yıkadıktan sonra iyice kurula."],"servingSuggestion":"Sofrada salata olarak paylaş; limonu isteyenler ayrıca ekleyebilir.","difficulty":"easy"}'::jsonb,array[]::text[]),
('havuc-tarator',null,true,'Yoğurtlu havuç tarator','Hafifçe sotelenmiş havuç, sarımsaklı yoğurtla buluşuyor. Az malzemeli, kaşık kaşık bir eşlikçi.',30,4,array['vegetarian','glutenFree']::text[],'economic','#E5B486','greens','side','["Havuçları yıka, ayıkla ve iri rendele. Tavada zeytinyağını ısıt.","Havucu ekleyip orta-kısık ateşte yaklaşık 10 dakika yumuşat; sık sık karıştır, kızartıp kurutma.","Havucu geniş bir tabağa alıp yaklaşık 10 dakika ılıt. Yoğurdu ezilmiş sarımsak ve tuzla karıştır.","Ilıyan havucu yoğurtla birleştir. Servis tabağına yayıp sun."]'::jsonb,'{"prepMinutes":10,"cookMinutes":10,"restMinutes":10,"tips":["Sıcak havucu doğrudan yoğurda ekleme; ılıtma süresi toplam hazırlığa dahildir.","Havucu çok ince rendelemek yerine iri rende kullanmak dokusunu korur."],"servingSuggestion":"Dolma veya fırın yemeğinin yanında küçük porsiyonlarla servis et.","difficulty":"easy"}'::jsonb,array['hob']::text[]),
('cacik',null,true,'Naneli cacık','Salatalık, sarımsak ve naneli yoğurt. Kıvamını suyla ayarladığın, sofranın serin eşlikçisi.',10,4,array['vegetarian','glutenFree']::text[],'economic','#D7DFC0','soup','side','["Salatalığı yıka, küçük küpler halinde doğra. Sarımsağı ez.","Yoğurdu sarımsak ve tuzla pürüzsüzleştir. Soğuk içme suyunu azar azar ekleyerek karıştır.","Salatalık ve naneyi ekle. Kaselere paylaştırıp zeytinyağını üzerine gezdir; serin servis et."]'::jsonb,'{"prepMinutes":10,"cookMinutes":0,"restMinutes":0,"tips":["Yoğurdun kıvamına göre suyun tamamını kullanman gerekmeyebilir; koyu seviyorsan azalt.","Servisten önce karıştır; salatalık bekledikçe su bırakabilir."],"servingSuggestion":"Bulgur pilavı, dolma veya fırında tavuğun yanında sun.","difficulty":"easy"}'::jsonb,array[]::text[]),
('un-helvasi',null,true,'Zeytinyağlı un helvası','Unu sabırla kavurup suyla hazırlanan şerbetle buluşturuyoruz. Süt ve tereyağı içermeyen sade bir helva.',40,4,array['vegan','vegetarian']::text[],'economic','#BF975D','rice','dessert','["Suyu ve şekeri küçük bir tencerede ısıt, şeker eriyince ocaktan al. Şerbeti kenarda ılık tut.","Kalın tabanlı geniş tencerede zeytinyağını hafifçe ısıt. Unu ekle; orta-kısık ateşte sürekli karıştırarak yaklaşık 20 dakika, rengi altın kahverengiye dönene kadar kavur.","Tencereyi ocaktan al. Ilık şerbeti sıçramaya karşı dikkat ederek azar azar ekle ve uzun saplı kaşıkla karıştır; yüzünü tencereye yaklaştırma.","Tekrar kısık ateşe al, 3–5 dakika karıştırarak toparlanmasını sağla. Ocağı kapatıp 5 dakika dinlendir.","Kaşıkla küçük porsiyonlar şekillendir. Tarçını üzerine serpip ılık servis et."]'::jsonb,'{"prepMinutes":5,"cookMinutes":30,"restMinutes":5,"tips":["Kavurma sırasında tencerenin tabanını ve kenarlarını sürekli sıyır; yüksek ateş unu yakar.","Şerbet eklerken oluşan buhara ve sıçramaya dikkat et. Renk ve kıvam ocak gücüne göre değişir."],"servingSuggestion":"Dört küçük tatlı porsiyonu olarak ılık sun.","difficulty":"medium"}'::jsonb,array['hob']::text[])
